use xiom.io;
interface Greetable {
  fn greet() -> Str;
}

type Person = {
  name: Str;
}

fn Person.greet(self) -> Str {
  return "Hi, I'm " + self.name;
}

fn introduce[T: Greetable](thing: &T) {
  io.println(thing.greet());
}

fn main() -> Int {
  let p = Person{ name: "Alex" };
  introduce(&p);
  return 0;
}
